const Modal = ({ isOpen, onClose, title, children, confirmText, onConfirm }) => {
    const modalRef = useRef(null);
    const firstButtonRef = useRef(null);
    const lastButtonRef = useRef(null);

    // Handle Escape key
    useEffect(() => {
        const handleKeyDown = (e) => {
            if (e.key === 'Escape') onClose();
            if (e.key === 'Tab') {
                if (!modalRef.current) return;
                const focusableElements = modalRef.current.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
                const first = focusableElements[0];
                const last = focusableElements[focusableElements.length - 1];

                if (e.shiftKey) {
                    if (document.activeElement === first) {
                        last.focus();
                        e.preventDefault();
                    }
                } else {
                    if (document.activeElement === last) {
                        first.focus();
                        e.preventDefault();
                    }
                }
            }
        };

        if (isOpen) {
            document.addEventListener('keydown', handleKeyDown);
            document.body.style.overflow = 'hidden';
            // Focus the first button (Cancel) after a short delay for animation
            setTimeout(() => {
                if (firstButtonRef.current) firstButtonRef.current.focus();
            }, 50);
        }

        return () => {
            document.removeEventListener('keydown', handleKeyDown);
            document.body.style.overflow = 'unset';
        };
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    return (
        <div 
            className="fixed inset-0 z-50 flex items-center justify-center p-4 modal-overlay"
            onClick={(e) => {
                if (e.target === e.currentTarget) onClose();
            }}
        >
            <div 
                ref={modalRef}
                className="bg-white rounded-2xl shadow-2xl max-w-md w-full overflow-hidden modal-content"
                role="dialog"
                aria-modal="true"
                aria-labelledby="modal-title"
                aria-describedby="modal-description"
            >
                <div className="p-6">
                    <div className="flex items-center justify-center w-12 h-12 mx-auto mb-4 bg-red-100 rounded-full">
                        <svg className="w-6 h-6 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                        </svg>
                    </div>
                    <h3 id="modal-title" className="text-xl font-semibold text-center text-gray-900 mb-2">
                        {title}
                    </h3>
                    <p id="modal-description" className="text-center text-gray-500 mb-6">
                        {children}
                    </p>
                    <div className="flex flex-col sm:flex-row gap-3">
                        <button
                            ref={firstButtonRef}
                            onClick={onClose}
                            className="flex-1 px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors focus:outline-none"
                        >
                            Cancel
                        </button>
                        <button
                            ref={lastButtonRef}
                            onClick={onConfirm}
                            className="flex-1 px-4 py-2 text-sm font-medium text-white bg-red-600 rounded-lg hover:bg-red-700 transition-colors focus:outline-none"
                        >
                            {confirmText}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

const ImagePreview = () => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isDeleted, setIsDeleted] = useState(false);

    const handleDelete = () => {
        setIsDeleted(true);
        setIsModalOpen(false);
    };

    if (isDeleted) {
        return (
            <div className="min-h-screen flex items-center justify-center flex-col gap-4">
                <div className="bg-green-100 text-green-800 px-6 py-4 rounded-xl shadow-sm flex items-center gap-3">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" />
                    </svg>
                    <span className="font-medium">Image successfully deleted.</span>
                </div>
                <button 
                    onClick={() => setIsDeleted(false)}
                    className="text-blue-600 hover:underline font-medium"
                >
                    Restore (demo only)
                </button>
            </div>
        );
    }

    return (
        <main className="min-h-screen py-12 px-4 flex flex-col items-center justify-center">
            <div className="max-w-2xl w-full bg-white rounded-3xl shadow-xl overflow-hidden border border-gray-100">
                <div className="aspect-video w-full bg-gray-200 relative overflow-hidden">
                    <img 
                        src="https://images.unsplash.com/photo-1472214103451-9374bd1c798e?auto=format&fit=crop&q=80&w=2070" 
                        alt="Beautiful mountain landscape"
                        className="w-full h-full object-cover"
                    />
                </div>
                <div className="p-8 text-center">
                    <h1 className="text-2xl font-bold text-gray-900 mb-2">Mountain Serenity</h1>
                    <p className="text-gray-500 mb-8 max-w-md mx-auto">
                        A peaceful view of the mountains at sunset, captured during my last trip to the Alps.
                    </p>

                    <button 
                        onClick={() => setIsModalOpen(true)}
                        className="trigger inline-flex items-center gap-2 px-6 py-3 bg-white text-red-600 border-2 border-red-100 rounded-xl font-semibold hover:bg-red-50 hover:border-red-200 transition-all active:scale-95 focus:outline-none"
                    >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                        </svg>
                        Delete Image
                    </button>
                </div>
            </div>

            <Modal 
                isOpen={isModalOpen} 
                onClose={() => setIsModalOpen(false)}
                title="Delete Image?"
                confirmText="Delete"
                onConfirm={handleDelete}
            >
                Are you sure you want to delete this image? This action cannot be undone and it will be permanently removed from your library.
            </Modal>
        </main>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ImagePreview />);
