                    onClick={() => setIsDeleted(false)}
                    className="text-blue-600 hover:underline font-medium"
                >
                    Restore (demo only)
                </button>
            </div>
        );
    }

    return (
        <main className="min-h-screen py-12 px-4 flex flex-col items-center justify-center">
